package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.rest.escalation.DuplicateOwnerException;

/**
 * The single duplicate check for create-owner: rejects a request whose derived
 * {@code identityKey} exactly equals an existing owner's, responding 409 via
 * {@link DuplicateOwnerException}. Consolidates the former separate telephone, email and
 * household checks into one {@link OwnerIdentities key}.
 *
 * <p>Runs after {@link NormalizeOwnerTelephone} and {@link NormalizeOwnerEmail} so the
 * request telephone is already E.164 and its email lower-cased. The household component
 * matches {@link AssignOwnerHousehold}: an owner opting in with {@code sharesHousehold}
 * gets the shared {@code householdId}, otherwise it is absent.
 */
public class RequireUniqueIdentity {

    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
            throws DuplicateOwnerException {
        String householdId = Boolean.TRUE.equals(request.getSharesHousehold())
                ? OwnerHouseholds.id(request.getLastName(), request.getAddress())
                : null;
        String identityKey = OwnerIdentities.key(request.getTelephone(), request.getEmail(), householdId);
        for (Owner existing : ownerRepository.findAll()) {
            if (identityKey.equals(OwnerIdentities.of(existing))) {
                throw new DuplicateOwnerException(identityKey);
            }
        }
    }
}
=== OwnerIdentities ===
package org.springframework.samples.petclinic.rest.function.owner;

import org.springframework.samples.petclinic.model.Owner;

/**
 * Shared owner identity for the create-owner pipeline: derives the single canonical
 * {@code identityKey} that consolidates all duplicate detection.
 *
 * <p>The key is {@code normalizedTelephone + '|' + (email or empty) + '|' + householdId},
 * with telephone canonicalized to E.164 (see {@link OwnerTelephones}) and email lower-cased
 * (see {@link OwnerEmails}); a missing component contributes an empty string. Two owners are
 * duplicates exactly when their whole keys are equal — so members of the same household
 * (same {@code householdId}) with different telephones have different keys and are both
 * allowed.
 */
public final class OwnerIdentities {

    private OwnerIdentities() {
    }

    /**
     * Canonical identity key for the given components. {@code telephone} is normalized to
     * E.164 and {@code email} lower-cased before assembly; any {@code null} component
     * contributes an empty string.
     */
    public static String key(String telephone, String email, String householdId) {
        return part(OwnerTelephones.toE164(telephone)) + "|" + part(OwnerEmails.normalize(email))
                + "|" + part(householdId);
    }

    /** Canonical {@link #key(String, String, String)} for an existing owner's stored fields. */
    public static String of(Owner owner) {
        return key(owner.getTelephone(), owner.getEmail(), owner.getHouseholdId());
    }

    private static String part(String value) {
        return value == null ? "" : value;
    }
}
